            .bytes()
            .await
            .map_err(|e| anyhow::anyhow!("Failed to read remote cache response body: {}", e))?;
        trace!("Downloaded {} bytes from remote cache", content.len());
        Self::extract_tarball(content.as_ref(), &cache_directory, &hash)
    }

